source.panelCss:
:scope { --cm-line: color-mix(in srgb, var(--cqs-accent) 34%, var(--cqs-border)); }
#cqs-panel { font-family: system-ui,-apple-system,'Pretendard','Noto Sans KR',sans-serif; border-color: var(--cqs-border); background: linear-gradient(180deg, var(--cqs-headerA), var(--cqs-canvas) 140px); box-shadow: 0 30px 70px -30px rgba(0,0,0,.8); }
#cqs-panel .cm-head { padding: 18px 18px 12px; border-bottom: 1px solid var(--cqs-border); }
#cqs-panel .cm-row { display: flex; align-items: center; gap: 9px; }
#cqs-panel .cm-mark { width: 9px; height: 9px; transform: rotate(45deg); background: var(--cqs-accent); }
#cqs-panel .cm-eb { flex: 1; min-width: 0; }
#cqs-panel .cqs-eyebrow { font-size: 9.5px; font-weight: 700; letter-spacing: .3em; color: var(--cqs-muted); }
#cqs-panel .cqs-close { width: 30px; height: 30px; font-size: 19px; color: var(--cqs-muted); background: transparent; box-shadow: inset 0 0 0 1px var(--cqs-border); }
#cqs-panel .cqs-close:hover { color: var(--cqs-accent); box-shadow: inset 0 0 0 1px var(--cm-line); }
#cqs-panel .cm-title h2 { margin: 14px 0 4px; font-size: 21px; font-weight: 700; letter-spacing: -.02em; color: var(--cqs-text); }
#cqs-panel .cm-sub p { margin: 0; font-size: 12px; color: var(--cqs-muted); }
#cqs-panel .cm-tools { display: flex; gap: 6px; padding: 12px 14px 4px; }
#cqs-panel .cm-find { flex: 1; min-width: 0; display: flex; }
#cqs-panel .cm-tools input { width: 100%; min-width: 0; padding: 9px 12px; border-radius: 8px; font: 13px system-ui,-apple-system,'Pretendard','Noto Sans KR',sans-serif; color: var(--cqs-text); background: var(--cqs-surface); border: 1px solid var(--cqs-border); }
#cqs-panel .cm-tools input:focus { outline: none; border-color: var(--cm-line); }
#cqs-panel .cm-tools .cqs-button { min-height: 36px; padding: 7px 11px; border-radius: 8px; font-size: 12px; color: var(--cqs-muted); background: var(--cqs-surface); }
#cqs-panel .cm-tools .cqs-button:hover { color: var(--cqs-accent); border-color: var(--cm-line); }
#cqs-panel .cqs-set-title { font-size: 10px; letter-spacing: .24em; color: var(--cqs-muted); }
#cqs-panel .cqs-set-title::after { content: ""; flex: 1; height: 1px; background: var(--cqs-border); order: 3; }
#cqs-panel .cqs-count { order: 2; color: var(--cqs-onAccent); background: var(--cqs-accent); }
#cqs-panel .cqs-qr { min-height: 56px; padding: 10px 12px; flex-direction: row; justify-content: flex-start; gap: 10px; text-align: left; border-color: var(--cqs-border); transition: border-color .18s, background .18s; }
#cqs-panel .cqs-qr:hover:not(:disabled) { transform: none; border-color: var(--cm-line); }
#cqs-panel .cqs-qr-icon { flex: none; width: 30px; height: 30px; border-radius: 7px; display: grid; place-items: center; font-size: 13px; background: var(--cqs-accentSoft); }
#cqs-panel .cqs-qr-label { font-size: 13px; font-weight: 600; text-align: left; }
#cqs-panel .cm-foot { border-top: 1px solid var(--cqs-border); background: var(--cqs-surface); }
#cqs-panel .cm-foot .cqs-status { border: 0; padding: 12px 16px; background: none; }
:scope > .cqs-handle { top: 42vh; top: 42dvh; border-radius: 10px 0 0 10px; color: var(--cqs-accent); background: var(--cqs-surface); border-color: var(--cm-line); }
:scope[data-side="left"] > .cqs-handle { border-radius: 0 10px 10px 0; }

source.chatCss:
:scope#bg1, :scope#bg_custom {
background-color: var(--cqs-canvas);
background-image:
radial-gradient(90% 60% at 50% 0%, color-mix(in srgb, var(--cqs-headerA) 85%, transparent), transparent 70%),
repeating-linear-gradient(135deg, color-mix(in srgb, var(--cqs-text) 2.5%, transparent) 0 1px, transparent 1px 7px);
}
:scope #chat {
background: color-mix(in srgb, var(--cqs-canvas) 90%, transparent);
border-inline: 1px solid var(--cqs-border);
}
:scope[data-cqs-mode="flat"] #chat .mes { border-bottom: 1px solid color-mix(in srgb, var(--cqs-border) 70%, transparent); padding-block: 16px; }
:scope[data-cqs-mode="flat"] #chat .mes[is_user="true"] {
background: linear-gradient(90deg, color-mix(in srgb, var(--cqs-accent) 7%, transparent), transparent 55%);
box-shadow: inset 2px 0 0 var(--cqs-accent);
}
:scope #chat .mes .ch_name .name_text { letter-spacing: .08em; font-weight: 600; }
:scope #chat .mes .timestamp { letter-spacing: .06em; text-transform: uppercase; font-size: .72em; }
:scope #chat .mes .avatar img { border-radius: 10px; box-shadow: 0 0 0 1px var(--cqs-border), 0 0 0 3px var(--cqs-canvas), 0 0 0 4px color-mix(in srgb, var(--cqs-accent) 30%, transparent); }
:scope #chat .mes_text em { font-style: italic; }
:scope #chat .mes_text q { border-bottom: 1px solid color-mix(in srgb, var(--cqs-accent) 35%, transparent); }
:scope #chat .mes_text blockquote { border-left: 1px solid var(--cqs-accent); background: transparent; padding-left: 14px; }
:scope #send_form {
border: 1px solid var(--cqs-border);
border-radius: 12px;
background: var(--cqs-surface);
box-shadow: 0 14px 30px -24px #000;
}
:scope #send_form:focus-within { border-color: color-mix(in srgb, var(--cqs-accent) 45%, var(--cqs-border)); box-shadow: 0 1px 0 0 var(--cqs-accent), 0 14px 30px -24px #000; }
:scope#options .options-content { border-radius: 10px; }

source.menuCss:
:scope#top-bar {
background: linear-gradient(180deg, var(--cqs-headerA), var(--cqs-canvas));
border-bottom: 1px solid var(--cqs-border);
box-shadow: 0 10px 26px -20px #000;
}
:scope#top-bar::after {
content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px; pointer-events: none;
background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--cqs-accent) 70%, transparent), transparent);
}
:scope .drawer-icon { color: var(--cqs-muted); }
:scope .drawer-icon:hover { color: var(--cqs-text); }
:scope .drawer-icon.openIcon { color: var(--cqs-accent); }
:scope .drawer-content { border: 1px solid var(--cqs-border); border-radius: 12px; box-shadow: 0 24px 50px -30px #000; }
